function Entry({ entry }: { entry: CommunityEntry }) { return <article className="community-entry"><div><span className="community-person-mark" aria-hidden>{entry.author.trim().slice(0, 1).toUpperCase() || "·"}</span><strong>{entry.author}</strong><time dateTime={entry.createdAt}>{new Date(entry.createdAt).toLocaleDateString()}</time></div><p>{entry.removed ? "This post was removed." : entry.body}</p>{entry.moderationReason && <p className="community-removal">Removal reason: {entry.moderationReason}</p>}{!entry.removed && <a href={`/#/report?target=${encodeURIComponent(`/community#view=help&topic=${entry.topicId}&entry=${entry.id}`)}&signin=1`}>Report this post</a>}</article>; }
