type DiscussionThread = { topic: Discussion; replies: Discussion[] };
const discussionLabels = { question: "Questions", general: "General", ideas: "Ideas", announcements: "Announcements" };
async function discoveryRead<T>(path: string): Promise<T> { const response = await fetch(`/api${path}`, { cache: "no-store", credentials: "omit" }); if (!response.ok) throw new Error("This public view is unavailable. Refresh to check its current visibility."); return await response.json() as T; }
