  const loading = settledScope !== scope, error = failure?.scope === scope ? failure.message : "", pageBusy = pageState.scope === scope && pageState.busy, pageError = pageState.scope === scope ? pageState.error : "";
  useEffect(() => { const change = () => setParams(communityParams()); window.addEventListener("hashchange", change); return () => window.removeEventListener("hashchange", change); }, []);
  useEffect(() => { const sequence = ++generation.current; pageLock.current = false; setPageState({scope,busy:false,error:""}); if (help || activity || ["people", "following"].includes(params.get("view") ?? "")) return; document.title = "Community · FlareGit"; setFailure(null); const valid = () => sequence === generation.current && currentScope.current === scope; const action = repo ? discoveryRead<Discussions | DiscussionThread>(`/public/${encodeURIComponent(repo)}/discussions${topic ? `/${encodeURIComponent(topic)}` : ""}`).then(value => { if (valid()) { if ("topic" in value) setThreadState({scope,value}); else setDiscussionsState({scope,value}); } }) : discoveryRead<RepositoryListing>(`/community/repositories?q=${encodeURIComponent(query)}`).then(value => { if (valid()) setListingState({scope,value}); }); void action.catch(cause => { if (valid()) setFailure({scope,message:cause instanceof Error ? cause.message : "Community unavailable."}); }).finally(() => { if (valid()) setSettledScope(scope); }); return () => { generation.current++; }; }, [repo, topic, query, scope, help, activity]);
